package com.example.studentmanagement.service;
import com.example.studentmanagement.dao.AttendanceDAO; import com.example.studentmanagement.model.Attendance; import org.springframework.stereotype.Service; import java.util.List;
@Service public class AttendanceService {private final AttendanceDAO dao; public AttendanceService(AttendanceDAO dao){this.dao=dao;} public List<Attendance> byStudent(int id){return dao.byStudent(id);} public Attendance add(Attendance a){validate(a);return dao.save(a);} public void update(int id,Attendance a){validate(a);if(dao.update(id,a)==0)throw new RuntimeException("Attendance record not found");} public void delete(int id){if(dao.delete(id)==0)throw new RuntimeException("Attendance record not found");} private void validate(Attendance a){if(a.getTotalClasses()==null||a.getAttendedClasses()==null||a.getTotalClasses()<0||a.getAttendedClasses()<0||a.getAttendedClasses()>a.getTotalClasses())throw new IllegalArgumentException("Invalid attendance values");}}
